import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Navigate } from 'react-router-dom';
import { LogIn, Eye, EyeOff, Globe } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslation, useLanguage } from '@/contexts/LanguageContext';
import type { User, UserRole } from '@/types';
import { initGoogleSignIn, loadGoogleScript, renderGoogleButton, resetGoogleInit } from '@/utils/googleAuth';
import { Environment } from '@/utils/environment';
import { apiService } from '@/services/api';
import { logger } from '@/utils/logger';

const LoginPage: React.FC = () => {
  const { isAuthenticated, login } = useAuth();
  const { t } = useTranslation();
  const { language, setLanguage } = useLanguage();
  const [isLoading, setIsLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [gisReady, setGisReady] = useState(false);
  const [error, setError] = useState<string>('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showLanguagePicker, setShowLanguagePicker] = useState(false);
  const googleBtnRef = useRef<HTMLDivElement | null>(null);
  const mountedRef = useRef(true);
  
  // Use environment-based configuration
  const clientId = Environment.googleClientId;
  const showDemoLogin = Environment.isDevelopment;

  const handleGoogleCredential = useCallback(
    async (credential: string) => {
      try {
        setIsGoogleLoading(true);
        setError('');

        try {
          // Try backend authentication
          await login(credential);
        } catch (backendError) {
          setError(t('auth.userNotFound'));
          throw backendError;
        }
      } catch (e) {
        logger.error('Google login error:', e);
      } finally {
        setIsGoogleLoading(false);
      }
    },
    [login, t]
  );

  // Initialize Google Identity Services and render button
  useEffect(() => {
    mountedRef.current = true;

    if (!clientId) {
      setGisReady(false);
      return () => {
        mountedRef.current = false;
      };
    }

    setIsGoogleLoading(true);
    setGisReady(false);

    // Add a small delay to ensure DOM is stable after redirects
    const initDelay = setTimeout(() => {
      if (!mountedRef.current) return;

      if (!clientId) {
        setGisReady(false);
        setIsGoogleLoading(false);
        return;
      }

      loadGoogleScript()
        .then(() => {
          if (!mountedRef.current) return;

          // Reset any previous initialization
          resetGoogleInit();

          setGisReady(true);
          initGoogleSignIn(clientId, handleGoogleCredential);

          // Ensure button container exists before rendering
          if (googleBtnRef.current) {
            renderGoogleButton(googleBtnRef.current);
          }
        })
        .catch((err) => {
          logger.error('Failed to load Google Identity Services:', err);
          if (mountedRef.current) {
            setGisReady(false);
          }
        })
        .finally(() => {
          if (mountedRef.current) {
            setIsGoogleLoading(false);
          }
        });
    }, 100);

    return () => {
      mountedRef.current = false;
      clearTimeout(initDelay);
    };
  }, [clientId, handleGoogleCredential]);

  // Re-render button when container ref changes
  useEffect(() => {
    if (gisReady && googleBtnRef.current && !isGoogleLoading && !isLoading) {
      // Small delay to ensure DOM is ready
      const renderDelay = setTimeout(() => {
        if (mountedRef.current && googleBtnRef.current) {
          renderGoogleButton(googleBtnRef.current);
        }
      }, 50);

      return () => clearTimeout(renderDelay);
    }
  }, [gisReady, isGoogleLoading, isLoading]);

  const handleUsernamePasswordLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!username || !password) {
      setError(t('loginPage.error'));
      return;
    }

    setIsLoading(true);

    try {
      // Use apiService which respects VITE_API_BASE_URL
      const response = await apiService.login(username, password);

      // The apiService.login already sets the tokens, now fetch current user
      const userWithRoles = await apiService.getCurrentUser();

      // Convert backend user to frontend User format using the same logic as Google login
      const authResponse = {
        access_token: response.access_token,
        refresh_token: response.refresh_token,
        roles: userWithRoles.roles,
        user: userWithRoles.user,
      };

      // Import helper functions
      const { extractString } = await import('../../../utils/sqlNull');
      const { getPrimaryRole } = await import('../../../constants');

      // Extract all available roles
      const availableRoles = authResponse.roles.map(r => r.role as UserRole);
      const primaryRole = getPrimaryRole(availableRoles);
      const userName = extractString(authResponse.user.name, authResponse.user.email.split('@')[0]);

      // Extract entity IDs from roles array
      let studentId: string | undefined;
      let employeeId: string | undefined;
      let applicationId: string | undefined;

      for (const roleEntity of authResponse.roles) {
        if (roleEntity.entity_type === 'mahasiswa' && roleEntity.entity_id) {
          studentId = roleEntity.entity_id;
        } else if (roleEntity.entity_type === 'dosen' && roleEntity.entity_id) {
          employeeId = roleEntity.entity_id;
        } else if (roleEntity.entity_type === 'applicant' && roleEntity.entity_id) {
          applicationId = roleEntity.entity_id;
        }
      }

      const user: User = {
        id: String(authResponse.user.id),
        email: authResponse.user.email,
        name: userName,
        role: primaryRole,
        availableRoles,
        studentId,
        employeeId,
        applicationId,
        roleEntities: authResponse.roles,
      };

      await login(user);
    } catch (err) {
      console.error('Login failed:', err);
      setError(err instanceof Error ? err.message : t('auth.loginFailed'));
    } finally {
      setIsLoading(false);
    }
  };

  const handleDemoLogin = async (role: UserRole) => {
    const demoUsers: Record<UserRole, User> = {
      guest: {
        id: 'guest-demo',
        email: 'guest@university.edu',
        name: 'Guest User',
        role: 'guest',
      },
      staff: {
        id: 'staff-1',
        email: 'staff@university.edu',
        name: 'Maria Staff',
        role: 'staff',
        employeeId: 'STF001',
      },
      student_applicant: {
        id: 'applicant-1',
        email: 'applicant@university.edu',
        name: 'John Applicant',
        role: 'student_applicant',
        applicationId: 'APP2024001',
      },
      student: {
        id: 'student-1',
        email: 'student@university.edu',
        name: 'Ahmad Mahasiswa',
        role: 'student',
        studentId: '2021001',
      },
      lecturer: {
        id: 'lecturer-1',
        email: 'lecturer@university.edu',
        name: 'Dr. Sarah Dosen',
        role: 'lecturer',
        employeeId: 'LEC001',
      },
      alumni: {
        id: 'alumni-1',
        email: 'alumni@university.edu',
        name: 'David Alumni',
        role: 'alumni',
        studentId: '2018001',
        graduationYear: 2022,
      },
      admin: {
        id: 'admin-1',
        email: 'admin@university.edu',
        name: 'Admin System',
        role: 'admin',
        employeeId: 'ADM001',
      },
    };

    await login(demoUsers[role]);
  };

  // Don't render redirect until we're sure we're not authenticated
  if (isAuthenticated) {
    return <Navigate to="/dashboard" replace />;
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 to-secondary-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        {/* Logo and Title */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 mb-4">
            <img 
              src={import.meta.env.BASE_URL + 'logo.png'} 
              alt="ADB Academic System Logo" 
              className="w-16 h-16 object-contain"
            />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            ADB Academic System
          </h1>
          <p className="text-gray-600">
            {t('loginPage.subtitle')}
          </p>
        </div>

        {/* Login Card */}
        <div className="bg-white rounded-xl shadow-lg p-8">
          <div className="space-y-6">
            {/* Error Message */}
            {error && (
              <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg text-sm">
                <p className="font-medium">{t('loginPage.error')}</p>
                <p className="mt-1">{error}</p>
              </div>
            )}

            {/* Username/Password Login Form */}
            <form onSubmit={handleUsernamePasswordLogin} className="space-y-4">
              <div>
                <p className="text-xs text-gray-600 mb-3 p-2 bg-blue-50 rounded border border-blue-200">
                  <strong>Kesulitan login dengan Google?</strong> Gunakan email sebagai username dan nama email diikuti "ADB" sebagai password.
                  <br/><br/>Contoh: untuk email <code className="text-blue-700">john.doe@digitalbdg.ac.id</code>, gunakan username: <code className="text-blue-700">john.doe@digitalbdg.ac.id</code> dan password: <code className="text-blue-700">john.doeADB</code>
                  <br/><br/>Setelah berhasil login, anda dapat mengubah password Anda di dengan membuka profil anda di kanan atas kemudian memilih menu settings.
                </p>
                <label htmlFor="username" className="block text-sm font-medium text-gray-700 mb-1">
                  {t('loginPage.username')}
                </label>
                <input
                  id="username"
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                  placeholder={t('loginPage.username')}
                  disabled={isLoading || isGoogleLoading}
                />
              </div>
              <div>
                <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
                  {t('loginPage.password')}
                </label>
                <div className="relative">
                  <input
                    id="password"
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full pr-10 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                    placeholder={t('loginPage.password')}
                    disabled={isLoading || isGoogleLoading}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(s => !s)}
                    disabled={isLoading || isGoogleLoading}
                    className="absolute inset-y-0 right-2 flex items-center px-2 text-gray-500"
                    aria-label={showPassword ? t('loginPage.hidePassword') : t('loginPage.showPassword')}
                    tabIndex={0}
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>
              <button
                type="submit"
                disabled={isLoading || isGoogleLoading}
                className="w-full btn-primary flex items-center justify-center"
              >
                {isLoading ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
                    {t('loginPage.loggingIn')}
                  </>
                ) : (
                  <>
                    <LogIn className="h-5 w-5 mr-2" />
                    {t('loginPage.login')}
                  </>
                )}
              </button>
            </form>

            {/* Divider */}
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-gray-300" />
              </div>
              <div className="relative flex justify-center text-sm">
                <span className="px-2 bg-white text-gray-500">{t('common.or')}</span>
              </div>
            </div>

            {/* Google OAuth Button */}
            <div className="w-full flex flex-col items-center">
              {(isGoogleLoading || isLoading) && (
                <div className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg bg-white text-sm text-gray-700">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-primary-600 mr-3"></div>
                  {isGoogleLoading ? t('loginPage.googleLoading') : t('auth.loading')}
                </div>
              )}
              {!isGoogleLoading && !isLoading && gisReady && clientId && (
                <div ref={googleBtnRef} className="w-full flex justify-center" />
              )}
              {!isGoogleLoading && !isLoading && (!gisReady || !clientId) && (
                <button
                  disabled
                  className="w-full flex items-center justify-center px-4 py-3 border border-gray-300 rounded-lg shadow-sm bg-white text-sm font-medium text-gray-700 opacity-60"
                >
                  <LogIn className="h-5 w-5 mr-3" />
                  {t('loginPage.clientIdMissing')}
                </button>
              )}
            </div>

            {/* Demo Login Section - Only in demo mode */}
            {showDemoLogin && (
              <>
                <div className="relative">
                  <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-gray-300" />
                  </div>
                  <div className="relative flex justify-center text-sm">
                    <span className="px-2 bg-white text-gray-500">{t('loginPage.demoLogin')}</span>
                  </div>
                </div>

                <div className="space-y-3">
                  <button
                    onClick={() => handleDemoLogin('student')}
                    disabled={isLoading || isGoogleLoading}
                    className="w-full btn-primary cursor-pointer"
                  >
                    {t('sidebar.studentPortal')}
                  </button>
                  <button
                    onClick={() => handleDemoLogin('lecturer')}
                    disabled={isLoading || isGoogleLoading}
                    className="w-full btn-secondary cursor-pointer"
                  >
                    {t('sidebar.lecturerPortal')}
                  </button>
                  <button
                    onClick={() => handleDemoLogin('admin')}
                    disabled={isLoading || isGoogleLoading}
                    className="w-full btn-secondary cursor-pointer"
                  >
                    {t('sidebar.adminPortal')}
                  </button>
                </div>
              </>
            )}
          </div>

          <div className="mt-6 text-center">
            <p className="text-xs text-gray-500">
              {t('common.agreeTerms')}
            </p>
          </div>
        </div>

        {/* Language Picker */}
        <div className="mt-4 flex justify-center">
          <div className="relative">
            <button
              onClick={() => setShowLanguagePicker(v => !v)}
              className="flex items-center space-x-2 px-4 py-2 bg-white border border-gray-300 rounded-lg shadow-sm hover:bg-gray-50 transition-colors cursor-pointer"
            >
              <Globe className="h-4 w-4 text-gray-600" />
              <span className="text-sm font-medium text-gray-700">{t(`language.${language}`)}</span>
            </button>
            
            {showLanguagePicker && (
              <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 w-48 bg-white border border-gray-200 rounded-lg shadow-lg z-50">
                <div className="py-1">
                  <button
                    onClick={() => {
                      setLanguage('id');
                      setShowLanguagePicker(false);
                    }}
                    className={`block w-full text-left px-4 py-2 text-sm cursor-pointer ${
                      language === 'id'
                        ? 'bg-primary-50 text-primary-700 font-medium'
                        : 'text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    {t('language.id')}
                    {language === 'id' && <span className="ml-2 text-primary-600">✓</span>}
                  </button>
                  <button
                    onClick={() => {
                      setLanguage('en');
                      setShowLanguagePicker(false);
                    }}
                    className={`block w-full text-left px-4 py-2 text-sm cursor-pointer ${
                      language === 'en'
                        ? 'bg-primary-50 text-primary-700 font-medium'
                        : 'text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    {t('language.en')}
                    {language === 'en' && <span className="ml-2 text-primary-600">✓</span>}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="text-center mt-8 text-sm text-gray-500">
          © 2024 ADB Academic System. All rights reserved.
        </div>
      </div>
    </div>
  );
};

export default LoginPage;